from typing import List

class Workflow:
    def __init__(self):
        self.name = 'MaxSumSubarray'

    def validate_input(self, arr: List[int], k: int) -> bool:
        return len(arr) >= k and k > 0

    def sliding_window(self, arr: List[int], k: int) -> int:
        if not self.validate_input(arr, k):
            return -1

        # Initialize window
        window_sum = sum(arr[:k])
        max_sum = window_sum

        # Slide the window
        for i in range(k, len(arr)):
            window_sum = window_sum - arr[i-k] + arr[i]
            max_sum = max(max_sum, window_sum)

        return max_sum

    def solve(self, arr: List[int], k: int) -> int:
        return self.sliding_window(arr, k)

